INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (105, 110, 160, 122601, 0.029, 101, 1, "仲間と夏を楽しむ、夏海の魔法士。自分を変えたいという固い決意で、障害物を無効化して走り続ける。", 1, 0, 1.5, 1, 1, 0);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (111, 105, 120, 122401, 0.014, 102, 0, "太陽よりも輝く、夏海の元気娘。　持ち前の身体能力で、どんなコースも柔軟に対応し、駆け抜ける。", 3, 1, 2.5, 2, 2, 0);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (105, 110, 350, 122501, 0.017, 103, 0, "波打ち際に煌めく、夏海の剣士。　日々の鍛錬で鍛えた脚で、長い距離も速度を落とさず走り切る。", 2, 0, 2.5, 3, 3, 1);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (105, 110, 130, 107501, 0.016, 104, 0, "海の幸に目がない、渚のお姫様。　『王家の装備』の力を解放し、障害物をものともせず前へと進む。", 3, 1, 1.5, 4, 4, 0);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (105, 110, 160, 107601, 0.014, 105, 1, "海でも主さまをお世話する、白浜の巫女。精霊の力で自身を加速させ、誰よりも速くゴールを目指す。", 1, 0, 2.5, 5, 5, 0);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (103, 120, 255, 107801, 0.029, 106, 0, "水着姿を恥じらう、ツンデレ猫娘。お得意の魔法で、対戦相手の走りを妨害し、レースを有利に進める。", 2, 0, 3.5, 6, 6, 1);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (103, 120, 160, 110601, 0.013, 107, 1, "優雅に浜を駆ける、真夏のマホ姫。しゃなりしゃなりと、雅な身のこなしで障害物を跳び越えていく。", 1, 0, 3.5, 7, 7, 0);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (103, 110, 350, 110401, 0.014, 108, 0, "浜の平和を守る、真夏の狼娘。　　獣人の強靭なスタミナで、レース　後半にスパートをかける。", 2, 0, 2.5, 8, 8, 1);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (100, 105, 130, 110501, 0.012, 109, 0, "浜に力強く舞う、真夏の南国娘。　レースの喧噪の中でも精神を乱さず後半に大きな捲りを見せる。", 3, 1, 1.5, 9, 9, 0);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (103, 105, 200, 115701, 0.014, 110, 1, "浜の事件を嗅ぎ付けた、真夏の　　名探偵。高い推理力と魔法で、的確に対戦相手の走りを乱す。", 1, 0, 2.5, 10, 10, 0);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (103, 105, 350, 113601, 0.071, 111, 0, "再び鎧を脱いだ、灼熱の騎士団長。実戦で培った判断力で、瞬時にバリアを展開し、障害物を無力化する。", 2, 0, 2.5, 11, 11, 1);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (103, 120, 130, 107901, 0.014, 112, 0, "水が苦手な、海辺の気まぐれ猫娘。浜に現れた美少女義賊は、対戦相手のスピードを奪いとる。", 3, 1, 1.5, 12, 12, 0);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (105, 110, 200, 108001, 0.022, 113, 1, "バカンスも効率第一な、海の傭兵。レースでも最高効率を求め、どんな状況でも隙のない走りを見せる。", 2, 0, 1.5, 13, 13, 0);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (108, 110, 160, 110301, 0.031, 114, 1, "真夏の太陽が良く似合う、海辺の　サレンママ。多才で器用、どんな　障害物もエレガントに越えていく。", 1, 0, 2.5, 14, 14, 0);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (105, 110, 130, 107701, 0.036, 115, 0, "海に嵐を呼ぶ夏のドジっ娘メイド。日頃から災難に慣れており、多少　のトラブルには動じたりしない。", 1, 1, 0.5, 15, 15, 0);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (95, 110, 350, 113101, 0.048, 116, 0, "粋な夏を愉しむ、若夏の姉御。　　流麗な身体捌きで、始・継・終と、UBを重ねるごとに、加速する。", 2, 0, 3.5, 16, 16, 1);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (105, 105, 130, 113301, 0.043, 117, 0, "夏のトキメキに触れた、オタク魔法少女。多彩な魔法を操り、少しずつ他の走者の速度を落とし続ける。", 3, 1, 1.5, 17, 17, 0);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (95, 105, 130, 113201, 0.018, 118, 0, "海獄に降臨せし、真夏の冥姫。　　レース後半に魔力を全解放し、　　蒼き疾風と成りて浜を駆け抜ける。", 2, 1, 1.5, 18, 18, 0);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (108, 110, 160, 117001, 0.021, 119, 1, "夏の夕を火花で彩る、渚の壊し屋。『壊し屋』の異名と過激な愛情は、対戦相手にプレッシャーを与える。", 2, 0, 2.5, 19, 19, 0);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (105, 110, 255, 113501, 0.036, 120, 0, "青春に生きる者を導く、夏の先生。夢へと邁進する聖母の加護が、その身をあらゆる困難から守る。", 1, 0, 2.5, 20, 20, 1);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (105, 105, 350, 113401, 0.02, 121, 0, "笑顔の応援が眩しい、夏の超能力　ガール。超能力を駆使して、どんな障害物もひとっ飛びで乗り越える。", 3, 0, 2.5, 21, 21, 1);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (105, 110, 130, 110101, 0.018, 122, 0, "海辺で大人の魅力を放つ、夏の　　セクシー先生。その魅力に囚われた対戦相手は、走りを乱してしまう。", 1, 1, 2.5, 22, 22, 0);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (111, 105, 160, 110001, 0.03, 123, 1, "水着も絶対外さない、夏のカリスマモデル。走りのバイブスは超テンアゲで、スピードはおにやば。", 3, 0, 3.5, 23, 23, 0);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (103, 110, 130, 117201, 0.027, 124, 0, "南の島も盛り上げる、真夏のアイドル。悪天候でも笑顔を絶やさず後半もリズムを上げて走り切る。", 1, 1, 1.5, 24, 24, 0);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (108, 105, 160, 117301, 0.02, 125, 1, "海原に美声を響かす、渚の歌姫。　守護の賛歌と精霊の加護により、　障害物から身を守る。", 2, 0, 3.5, 25, 25, 0);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (105, 110, 350, 117401, 0.04, 126, 0, "夏でも天邪鬼な、夕凪のテーラー。張り巡らされた魔法の糸で、他の走者の自由を奪う。", 3, 0, 2.5, 26, 26, 1);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (105, 110, 350, 117101, 0.009, 127, 0, "向日葵が良く似合う、海辺の　　　お姉ちゃん。秘密結社の一員で、　抜群の身体能力が一番の武器。", 1, 0, 3.5, 27, 27, 1);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (105, 120, 255, 122901, 0.022, 128, 0, "渚でおっとり、夏色うさぎっこ。　うさぎさんパワー全開で、ぴょん　ぴょんとコースを跳ね回る。", 1, 0, 3.5, 28, 28, 1);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (105, 110, 130, 122801, 0.028, 129, 0, "無邪気さ弾ける、夏色いたずら娘。砂浜でも、いたずらの準備は万端！レースに大波乱が巻き起こる！？", 3, 1, 2.5, 29, 29, 0);
INSERT INTO `v1_8a56aa3a766eda1671ac54e7c4821e361c4180d755440b144ab71ff14d6e3d70` VALUES (108, 105, 130, 122701, 0.023, 130, 1, "海でも真面目な、夏色優等生。　　高めた魔力を解き放ち、一瞬の内に他の走者を置き去りにする。", 2, 0, 3.5, 30, 30, 0);
